// ============================================================================================
//  00c_worldgen.js — THE OVERWORLD, GENERATED
// --------------------------------------------------------------------------------------------
//  WHAT THIS REPLACES. 00d_vgrove.js was 839 KB of JSON whose own header credited a `genworld.py`
//  that exists nowhere -- not on disk, not in git history, not in any branch. The world was a baked
//  artifact with no source: it could be edited by hand or thrown away, and nothing in between. That
//  is a fine place to be for a world you are finished with and an impossible one for a world about
//  to be rebuilt at nine times the size with a third island in it.
//
//  WHAT IS GENERATED AND WHAT IS NOT.
//    * ISLAND A -- the starter, everything west of the bridge -- is BAKED, byte for byte, as RLE.
//      It is where a new player's first twenty levels happen: four provinces, the landing beach, the
//      Cairnworks, hand-placed pillars and arrival tiles, all of it walked and tuned. A generator
//      that reproduced it "closely" would move a spawn or narrow a beach and nobody would find out
//      until a player got stuck. 43 KB of RLE for 74,324 land tiles. See tools/bake_island_a.py.
//    * ISLAND B -- everything east of the bridge -- is GENERATED, and the numbers it is generated
//      against are measured off the artifact rather than invented: 371,974 land tiles in 501,120
//      cells (74.2%), solid inside r=240 of the island centre and ragged out to r=448, with a
//      per-band ground mix and a spawn density this file's audit compares against.
//    * `rings`, `pillars` and `arrivals` are COPIED VERBATIM. They are hand-tuned data about level
//      bands, province names and fast-travel points, not shape. Regenerating them would risk a lot
//      and gain nothing.
//
//  DETERMINISM IS A CO-OP REQUIREMENT, NOT A NICETY. Two peers each build their own world from this
//  file and then exchange positions in tile coordinates. If their worlds differ by one tile, one
//  player walks through a rock the other is standing on. So:
//    * one seeded PRNG, no Math.random, no Date
//    * NO Math.sin/cos/atan2/pow ANYWHERE IN THE TILE DECISION. ECMAScript does not specify the
//      results of the transcendental functions -- they are allowed to differ between engines, and
//      do, in the last bits. Integer-hash value noise, squared distances and Math.sqrt only.
//      (Math.sqrt IS specified exactly: IEEE-754 requires it to be correctly rounded.)
//    * WORLD_HASH at the end, so a mismatch is caught at the handshake instead of discovered as a
//      desync forty minutes in.
//
//  THIS FILE LOADS BEFORE 01_constants.js, so there is no TILE, no LV_CAP, no W/H. Everything here
//  is in TILES and plain numbers. Do not reach for a game constant; take it as an argument.
// ============================================================================================

// ---- the seed -------------------------------------------------------------------------------
// One number decides the whole world east of the bridge. Changing it is a content change: it moves
// every coastline, every rock and every spawn, and it invalidates WORLD_HASH, saved fog (the fog key
// carries the room shape) and any in-flight co-op session. It is not a tuning dial.
const WORLD_SEED = 0x51ee9d3b;

// ---- integer hash and value noise -----------------------------------------------------------
// A 32-bit avalanche over three integers. `>>> 0` after every step, because JS bitwise ops produce
// SIGNED 32-bit results and one missing coercion turns a hash into a sign-flip pattern that looks
// like noise until you plot it.
function wgHash(x, y, s) {
  let h = (x | 0) * 0x27d4eb2d ^ (y | 0) * 0x165667b1 ^ (s | 0) * 0x9e3779b9;
  h >>>= 0;
  h = (h ^ (h >>> 15)) >>> 0;
  h = Math.imul(h, 0x2545f491) >>> 0;
  h = (h ^ (h >>> 13)) >>> 0;
  h = Math.imul(h, 0x85ebca6b) >>> 0;
  return (h ^ (h >>> 16)) >>> 0;
}
// hash -> [0,1)
function wgRand(x, y, s) { return wgHash(x, y, s) / 4294967296; }

// Value noise: hash the four lattice corners and interpolate with a smoothstep. Not gradient noise
// -- value noise has visible lattice structure at low octave counts, which does not matter here
// because it is summed over four octaves and then thresholded, and it costs no trig.
function wgVal(fx, fy, s) {
  const x0 = Math.floor(fx), y0 = Math.floor(fy);
  let tx = fx - x0, ty = fy - y0;
  tx = tx * tx * (3 - 2 * tx);
  ty = ty * ty * (3 - 2 * ty);
  const a = wgRand(x0,     y0,     s), b = wgRand(x0 + 1, y0,     s);
  const c = wgRand(x0,     y0 + 1, s), d = wgRand(x0 + 1, y0 + 1, s);
  const top = a + (b - a) * tx, bot = c + (d - c) * tx;
  return top + (bot - top) * ty;
}
// Four octaves, halving amplitude, doubling frequency. Returns [0,1).
function wgFbm(fx, fy, s, oct) {
  let v = 0, amp = 0.5, f = 1, norm = 0;
  for (let i = 0; i < (oct || 4); i++) {
    v += wgVal(fx * f, fy * f, s + i * 7919) * amp;
    norm += amp; amp *= 0.5; f *= 2;
  }
  return v / norm;
}

// ---- island A, baked ------------------------------------------------------------------------
// Decode "<char><count>" runs, rows split on '|', every row pre-filled with water so a trailing
// water run can be dropped by the encoder. Eight lines, and it is the whole reason the download is
// 43 KB instead of 250.
function wgRleRows(rle, w, h) {
  const out = new Array(h);
  const rows = rle.split('|');
  for (let y = 0; y < h; y++) {
    const src = rows[y] || '';
    const row = new Array(w).fill('w');
    let x = 0, i = 0;
    while (i < src.length && x < w) {
      const ch = src[i++];
      let n = 0;
      while (i < src.length && src.charCodeAt(i) >= 48 && src.charCodeAt(i) <= 57) {
        n = n * 10 + (src.charCodeAt(i++) - 48);
      }
      if (n === 0) n = 1;
      for (let k = 0; k < n && x < w; k++) row[x++] = ch;
    }
    out[y] = row;
  }
  return out;
}

// 74324 land tiles, bbox 28,206..351,559. Generated by tools/bake_island_a.py from the retired
// 00d_vgrove.js artifact -- see that script for why this half of the world is bytes and
// not a generator. Runs are "<char><count>", count omitted at 1, rows joined with "|",
// trailing water dropped because the decoder fills water first.
