// ---- island B's coastline -------------------------------------------------------------------
// A radial field with a domain-warped, fBm-perturbed threshold. The numbers are MEASURED off the
// world this replaces, not chosen:
//
//   radius from the island centre     land fraction in the artifact
//     up to 240                        1.00
//     240-280                          0.96
//     280-320                          0.79
//     320-360                          0.57      <- the 50% crossing sits here, so ISLE_B_R ~ 330
//     360-400                          0.35
//     400-440                          0.13
//     440-480                          0.01
//
// so `1 - r/330 + noise` thresholded at 0, with noise amplitude ~0.30, reproduces that curve: at
// r=400 it needs noise > 0.21 of a ~±0.30 range, which is about an eighth of the time.
// TUNED AGAINST THE AUDIT, NOT DERIVED. 330 is what the land-fraction curve above predicts, and it
// came out 8% short on total land: 341,866 tiles against the artifact's 371,974. Land area goes as
// the square of the radius, so 8% of area is 4% of radius -- 330 * 1.04 = 343. The prediction was not
// wrong, it was incomplete: the curve is measured over full radial rings, and the eastern rings are
// clipped by the map edge, so the same radius encloses less land here than the ring statistics imply.
const ISLE_B_R    = 343;     // the 50% coastline radius, in tiles
const ISLE_B_AMP  = 0.30;    // how far the coast wanders, as a fraction of ISLE_B_R
const ISLE_B_FREQ = 1 / 46;  // coastline detail: one lattice cell per 46 tiles
const WARP_AMP    = 26;      // tiles of domain warp, so the coast is not a noisy circle
const WARP_FREQ   = 1 / 120;

// A distance field in SQUARED tiles until the last step, because a squared compare needs no sqrt
// and sqrt is the only transcendental this file is allowed.
function wgLandAt(tx, ty) {
  // domain warp FIRST, at a much lower frequency than its own amplitude, which is what turns a
  // circle into a coastline with bays instead of into fuzz
  const wx = tx + (wgVal(tx * WARP_FREQ, ty * WARP_FREQ, WORLD_SEED + 101) * 2 - 1) * WARP_AMP;
  const wy = ty + (wgVal(tx * WARP_FREQ, ty * WARP_FREQ, WORLD_SEED + 202) * 2 - 1) * WARP_AMP;
  const dx = wx - WG_RINGS.main.cx, dy = wy - WG_RINGS.main.cy;
  const r = Math.sqrt(dx * dx + dy * dy);
  const n = (wgFbm(tx * ISLE_B_FREQ, ty * ISLE_B_FREQ, WORLD_SEED + 303, 4) * 2 - 1) * ISLE_B_AMP;
  return (1 - r / ISLE_B_R + n) > 0;
}

// ---- island B's ground ----------------------------------------------------------------------
// PER 2x2 BLOCK, NOT PER TILE, and that is measured too: the artifact's horizontal runs of one
// character are overwhelmingly EVEN in length (27,139 runs of 2, 8,171 of 4, 3,089 of 6, and 122 of
// 1) with a mean of 3.1. Its generator worked on a 2x2 grid and drew each block independently, so
// the ground is dithered at 2-tile granularity rather than laid out in coherent patches. Matching
// that is both simpler and more faithful than inventing regions the world never had.
//
// The mixes are the measured per-band histograms, cumulative so one random number picks one char.
// Band is the radial approximation grvBandAt itself uses off-land -- 3 + floor(f*6) of f =
// dist(core)/rmax -- so this table and the game's own band function cannot disagree about where a
// band is.
//   r = scree and bare rock   d = dirt / open ground   e = burnt ash flats   g = grassland
//   k = boulder (blocks a small circle)   c/s = spawn markers, consumed by 02_worldbuild's sweep
const WG_MIX = [
  // band 3: the bridge landing, still green
  [['d',0.310],['r',0.594],['g',0.866],['e',0.934],['k',0.979],['c',0.994],['s',1.000]],
  // band 4
  [['r',0.411],['d',0.778],['g',0.859],['e',0.926],['k',0.983],['c',0.995],['s',1.000]],
  // band 5
  [['r',0.404],['d',0.784],['e',0.856],['g',0.927],['k',0.983],['c',0.993],['s',1.000]],
  // band 6: ash starts to win
  [['r',0.425],['d',0.708],['e',0.886],['k',0.944],['g',0.984],['c',0.993],['s',1.000]],
  // band 7
  [['r',0.360],['e',0.700],['d',0.911],['k',0.968],['g',0.983],['c',0.994],['s',1.000]],
  // band 8: the rim, burnt through
  [['e',0.446],['r',0.761],['d',0.927],['k',0.983],['c',0.993],['s',1.000]]
];
function wgGroundFor(band, roll) {
  const row = WG_MIX[Math.max(0, Math.min(WG_MIX.length - 1, band - 3))];
  for (let i = 0; i < row.length; i++) if (roll < row[i][1]) return row[i][0];
  return row[row.length - 1][0];
}

// ---- the generator --------------------------------------------------------------------------
function genWorld() {
  const W = WG_W, H = WG_H, R = WG_RINGS;
  const x1 = R.bridge.x1;

  // rows as arrays of chars: the room builder wants strings, and joining once at the end is far
  // cheaper than concatenating a 1160-char string a character at a time
  const rows = wgRleRows(ISLE_A_RLE, ISLE_A_W, H);
  for (let y = 0; y < H; y++) {
    const row = rows[y];
    row.length = W;
    for (let x = ISLE_A_W; x < W; x++) row[x] = 'w';
  }

  // --- island B's land, then its ground ---
  const cx = R.core.cx, cy = R.core.cy, rmax = R.rmax;
  for (let y = 0; y < H; y++) {
    const row = rows[y];
    for (let x = x1; x < W; x++) {
      if (!wgLandAt(x, y)) continue;
      const ddx = x - cx, ddy = y - cy;
      const f = Math.min(1, Math.sqrt(ddx * ddx + ddy * ddy) / rmax);
      const band = Math.max(3, Math.min(8, 3 + Math.floor(f * 6)));
      // one roll per 2x2 block, so the block gets one character
      const roll = wgRand(x >> 1, y >> 1, WORLD_SEED + 404 + band);
      row[x] = wgGroundFor(band, roll);
    }
  }

  // --- the bridge ---
  // A causeway of 'b' at cy, from x0 to x1, w tiles wide. It is the only link between the islands
  // and the flood fill below seeds from its eastern end, so it is stamped before connectivity.
  const b = R.bridge, half = (b.w / 2) | 0;
  for (let y = b.cy - half; y < b.cy - half + b.w; y++) {
    if (y < 0 || y >= H) continue;
    for (let x = b.x0; x <= b.x1; x++) rows[y][x] = 'b';
  }

  // --- guarantee the ground under everything that MUST exist ---
  // The rift portal sits at r=316 from the island centre, which is inside the ragged coastal band:
  // a noise field is entitled to put water there, and a portal in the sea is an unreachable
  // endgame. Same for every fast-travel pillar. Stamped as discs, after the coastline and before
  // the connectivity fill, so the fill can also reach them.
  const stamp = (tx, ty, rad, ch) => {
    for (let y = ty - rad; y <= ty + rad; y++) {
      if (y < 0 || y >= H) continue;
      for (let x = tx - rad; x <= tx + rad; x++) {
        if (x < x1 || x >= W) continue;                 // never touch island A
        const dx = x - tx, dy = y - ty;
        if (dx * dx + dy * dy > rad * rad) continue;
        if (rows[y][x] === 'b') continue;
        rows[y][x] = ch;
      }
    }
  };
  stamp(R.portal.x, R.portal.y, 10, 'd');
  for (const p of WG_PILLARS) if (p.tx >= x1) stamp(p.tx, p.ty, 7, 'd');

  // --- THE APPROACH ROAD, AND WHY IT IS NOT OPTIONAL ---
  // The bridge lands at x=464, which is r=340 from the island centre -- INSIDE the ragged coastal
  // band, where the field is a coin flip. The first run of this generator drowned all 341,052 tiles
  // of island B for exactly that reason: the flood fill crossed the causeway, filled a 177-tile
  // apron, hit a wall of noise-water and stopped, so every tile beyond it counted as an orphan and
  // the whole eastern world went into the sea. The audit reported it as "island B land tiles: 75631,
  // want 371974" and the picture would have been an empty ocean with a pier in it.
  //
  // So the causeway gets a landfall that is guaranteed rather than hoped for: a three-tile dirt
  // SPINE from the bridge mouth to the island's solid core, with band ground filled in around it.
  // The spine wanders on its own low-frequency noise so it reads as an isthmus and not as a ruler
  // line, and the ground beside it is drawn from the same per-band mix as everywhere else -- what is
  // guaranteed is that you can WALK it, not that it looks different.
  const solidR = 240;                                   // inside this radius the field is always land
  const roadTo = Math.round(R.main.cx - solidR) + 8;    // ~572: comfortably into the core
  for (let x = x1; x <= roadTo; x++) {
    const wob = Math.round((wgVal(x / 70, 0.5, WORLD_SEED + 505) * 2 - 1) * 11);
    const y0 = b.cy + wob;
    for (let dy = -9; dy <= 9; dy++) {
      const y = y0 + dy;
      if (y < 1 || y >= H - 1) continue;
      if (rows[y][x] === 'b') continue;
      if (Math.abs(dy) <= 1) { rows[y][x] = 'd'; continue; }   // the walkable spine
      if (rows[y][x] !== 'w') continue;                        // do not overwrite real land
      // taper: the further from the spine, the less likely the sea has been pushed back
      if (wgRand(x, y, WORLD_SEED + 606) < (9 - Math.abs(dy)) / 9) {
        const ddx = x - cx, ddy = y - cy;
        const f = Math.min(1, Math.sqrt(ddx * ddx + ddy * ddy) / rmax);
        const band = Math.max(3, Math.min(8, 3 + Math.floor(f * 6)));
        rows[y][x] = wgGroundFor(band, wgRand(x >> 1, y >> 1, WORLD_SEED + 404 + band));
      }
    }
  }
  // NO 'P' HERE. 'P' is the PLAYER SPAWN, and 02_worldbuild's sweep assigns r.px/r.py from every one
  // it finds -- so the last one in scan order wins. Island A's baked slice already carries the one
  // real spawn on the landing beach; writing a second at the rift moved a brand new Lv1 character to
  // the Lv50 rim, and the only trace was `P:2` in a histogram. rings.portal is read directly by
  // corruptAt and drawn as a landmark; it needs no marker tile at all.

  // --- CONNECTIVITY: one island, or the pieces are content nobody can reach ---
  // An explicit Int32Array stack, never recursion. At this size the reachable set is over 370,000
  // tiles and a recursive flood fill would blow the JS stack; at the three-island size it is 1.86M.
  const seen = new Uint8Array(W * H);
  const stack = new Int32Array(W * H);
  let sp = 0;
  const wet = (ch) => ch === 'w';
  // seed from the bridge's eastern mouth, which is the only way a player arrives
  for (let y = b.cy - half; y < b.cy - half + b.w; y++) {
    if (y < 0 || y >= H) continue;
    const i = y * W + b.x1;
    if (!wet(rows[y][b.x1]) && !seen[i]) { seen[i] = 1; stack[sp++] = i; }
  }
  let reached = 0;
  while (sp > 0) {
    const i = stack[--sp];
    reached++;
    const x = i % W, y = (i - x) / W;
    if (x + 1 < W  && !seen[i + 1] && !wet(rows[y][x + 1])) { seen[i + 1] = 1; stack[sp++] = i + 1; }
    if (x - 1 >= 0 && !seen[i - 1] && !wet(rows[y][x - 1])) { seen[i - 1] = 1; stack[sp++] = i - 1; }
    if (y + 1 < H  && !seen[i + W] && !wet(rows[y + 1][x])) { seen[i + W] = 1; stack[sp++] = i + W; }
    if (y - 1 >= 0 && !seen[i - W] && !wet(rows[y - 1][x])) { seen[i - W] = 1; stack[sp++] = i - W; }
  }
  // anything east of the bridge the fill never touched is an orphan islet: drown it. Island A is
  // exempt -- it is baked, it is reached through the bridge from the other side, and the seed above
  // deliberately faces east.
  let drowned = 0;
  for (let y = 0; y < H; y++) {
    const row = rows[y];
    for (let x = x1; x < W; x++) {
      if (row[x] !== 'w' && !seen[y * W + x]) { row[x] = 'w'; drowned++; }
    }
  }

  const map = new Array(H);
  for (let y = 0; y < H; y++) map[y] = rows[y].join('');

  return {
    big: true, w: W, h: H, name: 'The Sundered Isles',
    // A FRESH COPY OF THE SPEC, not the module's own object. 02_worldbuild pushes a ninth band name
    // onto rings.names and _territories caches its table on rings, so handing out WG_RINGS itself
    // means the second call to genWorld() -- which is how the audit proves determinism -- gets a spec
    // the first call's world already modified.
    rings: JSON.parse(JSON.stringify(WG_RINGS)),
    pillars: JSON.parse(JSON.stringify(WG_PILLARS)),
    map: map,
    // measurements, for _worldaudit.js and for the co-op handshake. Not used by the game.
    _gen: { reached: reached, drowned: drowned, seed: WORLD_SEED }
  };
}

// ---- the fingerprint ------------------------------------------------------------------------
// FNV-1a over the tile data plus a CANONICAL form of everything hand-authored. Two peers compare this
// at the handshake: a mismatch is a different world, and it is far better to refuse the join than to
// discover it as a desync when one player walks into a rock the other cannot see.
//
// NOT JSON.stringify(def.rings). The first version did exactly that and the audit caught it: the hash
// was not reproducible from the same world. `rings` is handed to 02_worldbuild, which PUSHES a ninth
// entry onto rings.names, and to _territories, which caches _terr on it -- so by the time anything
// re-checks, stringifying it includes a whole territory table and a band name that were not there at
// load. A fingerprint has to be built from named fields, so that what it covers is a decision rather
// than whatever happens to be hanging off the object at the moment it is called.
function worldHash(def) {
  let h = 0x811c9dc5;
  const mix = (s) => {
    s = String(s);
    for (let i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h = Math.imul(h, 0x01000193) >>> 0;
    }
  };
  for (const row of def.map) mix(row);
  mix(def.w + 'x' + def.h + '|' + WORLD_SEED);
  const R = def.rings;
  mix([R.starter.cx, R.starter.cy, R.starter.r,
       R.bridge.x0, R.bridge.x1, R.bridge.cy, R.bridge.w,
       R.core.cx, R.core.cy, R.main.cx, R.main.cy, R.main.r,
       R.rmax, R.grindR, R.portal.x, R.portal.y].join(','));
  // the first eight names only: the ninth is appended at build time from rings.grind[0]
  for (let i = 0; i < 8; i++) { const n = R.names[i]; mix(n.n + ':' + n.lv + '-' + n.lv2); }
  for (const g of R.grind) mix(g);
  for (const z of R.starterZones) mix(z.n + ':' + z.lv + '-' + z.lv2);
  for (const p of def.pillars) mix(p.b + ':' + p.name + ':' + p.tx + ',' + p.ty);
  return ('0000000' + h.toString(16)).slice(-8);
}

ROOM_DEFS['G'] = genWorld();
const WORLD_HASH = worldHash(ROOM_DEFS['G']);
